# SPDX-License-Identifier: AGPL-3.0-only
import json,time,urllib.request,pathlib,sys,os
out=pathlib.Path('/tmp/atlas-nvidia-mtp'); arm=sys.argv[1]
base='http://127.0.0.1:8892'
for attempt in range(600):
    try:
        urllib.request.urlopen(base+'/v1/models',timeout=2);break
    except Exception:
        pid=int((out/f"{arm}.pid").read_text())
        os.kill(pid,0)
        time.sleep(2)
else: raise RuntimeError('server not ready')
prompts=['What is 12 times 8? Answer briefly.', 'In two sentences, explain what a Merkle tree is and why it is useful.', 'Write a Python function that reverses a string, then explain it in one sentence.']
requests=[{'model':'qwen4exp-nvfp4','messages':[{'role':'user','content':p}],'temperature':0,'seed':123,'max_tokens':250} for p in prompts]
tool=json.loads(pathlib.Path('/tmp/atlas-mtp-final/tool-request.json').read_text());tool['model']='qwen4exp-nvfp4'; requests.append(tool)
for i,body in enumerate(requests):
    t=time.monotonic();req=urllib.request.Request(base+'/v1/chat/completions',data=json.dumps(body).encode(),headers={'Content-Type':'application/json'})
    with urllib.request.urlopen(req,timeout=300) as r: result=json.load(r)
    record={'arm':arm,'request':body,'response':result,'wall_s':time.monotonic()-t}
    (out/f'{arm}-{i}.json').write_text(json.dumps(record,indent=2));print(json.dumps(record),flush=True)

