# SPDX-License-Identifier: AGPL-3.0-only
import json,pathlib,sys,statistics
p=pathlib.Path('/tmp/atlas-nvidia-mtp');arm=sys.argv[1]
def normalize(c):
 c=json.loads(json.dumps(c))
 for choice in c:
  for call in choice.get('message',{}).get('tool_calls',[]):call.pop('id',None)
 return c
summary=[]
for i in range(4):
 a=json.loads((p/f'serial-{i}.json').read_text());b=json.loads((p/f'{arm}-{i}.json').read_text())
 summary.append({'prompt':i,'identical':normalize(a['response']['choices'])==normalize(b['response']['choices'])})
for name in ['serial',arm]:
 f=p/f'ab-{name}.json'
 if f.exists():
  v=json.loads(f.read_text());summary.append({'arm':name,'repeats':len(v),'median_wall_s':statistics.median(r['wall_s'] for r in v),'median_server_response_tps':statistics.median(r['response']['usage']['response_token/s'] for r in v)})
if (p/f'ab-{arm}.json').exists():
 a=json.loads((p/'ab-serial.json').read_text());b=json.loads((p/f'ab-{arm}.json').read_text());summary.append({'long_choices_identical':all(normalize(r['response']['choices'])==normalize(a[0]['response']['choices']) for r in a+b)})
(p/f'comparison-{arm}.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
